<template>
 <a-card :bordered="false">
  <div class="table-page-search-wrapper"><a-form layout="inline" @keyup.enter.native="load()"><a-row :gutter="24">
   <a-col :md="10" :sm="24"><a-form-item label="联系表 / 订单 / 客户"><a-input v-model="keyword" placeholder="请输入联系表号、销售订单号或客户" style="width:360px" /></a-form-item></a-col>
   <a-col :md="6" :sm="24"><a-form-item label="状态"><a-select v-model="state" allow-clear placeholder="请选择状态" style="width:170px"><a-select-option v-for="(name,key) in states" :key="key" :value="key">{{name}}</a-select-option></a-select></a-form-item></a-col>
   <a-col :md="8" :sm="24"><a-button type="primary" @click="load()">查询</a-button><a-button style="margin-left:8px" @click="keyword='';state=undefined;load()">重置</a-button></a-col>
  </a-row></a-form></div>
  <div class="operator">
   <a-button type="primary" :disabled="!editable(selected)" @click="edit(selected)">编辑联系表</a-button>
   <a-button icon="upload" :disabled="!ownedState(['draft','returned'])" @click="act('submit')">提交审核</a-button>
   <a-button icon="check" :disabled="!reviewable" @click="act('approve')">审核</a-button>
   <a-tooltip title="仅生产审核领导可反审核尚未下发车间的联系表；填写原因后退回草稿"><span><a-button icon="stop" :disabled="!canUnapprove" @click="act('unapprove')">反审核</a-button></span></a-tooltip>
   <a-button icon="rollback" :disabled="!reviewable" @click="act('return')">退回</a-button>
   <a-button :disabled="!ownedState(['pending','approved'])" @click="act('withdraw')">撤回修改</a-button>
   <a-button :disabled="!ownedState(['draft','returned','pending','approved'])" @click="act('cancel')">撤销联系表</a-button>
   <a-button type="primary" :disabled="!options.isCoordinator || !selected || !['approved','distributed','scheduled'].includes(selected.workflow_status)" @click="open(selected,'distribute')">统筹分配车间</a-button>
   <a-button type="primary" :disabled="!myWorkshopState || myWorkshopState.workflow_status!=='pending'" @click="act('accept')">本车间主任接单</a-button>
   <a-button :disabled="!myWorkshopState || !['accepted','scheduled'].includes(myWorkshopState.workflow_status)" @click="open(selected,'plan')">本车间排班</a-button>
   <a-button :disabled="!selected || !['distributed','scheduled'].includes(selected.workflow_status)" @click="goMaterial(selected.head_id)">领料 / 补料 / 退料</a-button>
   <a-button icon="reload" @click="load(false)">刷新</a-button><a-button v-if="options.canConfigure" icon="setting" @click="settings=true">生产人员配置</a-button>
  </div>
  <a-alert style="margin-bottom:12px" type="info" show-icon :message="'审核人：'+userName(options.reviewer_id)+'；生产统筹：'+userName(options.coordinator_id)+'；'+workshops.map((name,i)=>name+'主任：'+userName(options['workshop'+(i+1)+'_director_id'])).join('；')" />
  <a-table :columns="columns" :data-source="rows" row-key="head_id" bordered size="middle" :loading="loading" :pagination="pagination" :scroll="{x:1200}" :row-selection="{type:'radio',selectedRowKeys:selectedKeys,onChange:keys=>selectedKeys=keys}" @change="onPage"><template slot="state" slot-scope="value"><a-tag>{{states[value]}}</a-tag></template><template slot="workshops" slot-scope="_,r"><div v-for="w in r.workshops" :key="w.workshop_no">{{workshops[w.workshop_no-1]}}：{{workshopStates[w.workflow_status]}}</div></template><template slot="action" slot-scope="_,r"><a @click="open(r,'view')">查看</a></template></a-table>
  <j-modal :visible="visible" :title="mode==='edit'?'生产任务联系表':mode==='distribute'?'生产统筹分配车间':mode==='plan'?'本车间人员与排班':'查看生产任务联系表'" fullscreen switchFullscreen :footer="null" :mask-closable="false" @cancel="visible=false">
   <a-spin :spinning="saving">
    <a-descriptions bordered size="small" :column="3"><a-descriptions-item label="联系表编号">{{form.number || '保存后生成'}}</a-descriptions-item><a-descriptions-item label="销售订单">{{form.order_number}}</a-descriptions-item><a-descriptions-item label="状态">{{states[form.workflow_status] || '新建'}}</a-descriptions-item><a-descriptions-item label="客户">{{form.customer_name}}</a-descriptions-item><a-descriptions-item label="统一交货日期">{{form.delivery_date}}</a-descriptions-item><a-descriptions-item label="数量单位">吨</a-descriptions-item></a-descriptions>
    <a-alert v-if="form.gapChanged" style="margin-top:14px" type="warning" show-icon message="仓库预留已变化。请销售与主任协调核对；下达的生产数量不会自动改变。" />
    <h3>产品及生产要求</h3><div class="table-scroll"><table class="details"><thead><tr><th>产品 / 牌号商标 / 规格型号</th><th>订单需求</th><th>开单时预留</th><th>当前预留</th><th>当前缺口</th><th>本次生产数量</th><th>调整原因</th></tr></thead><tbody><tr v-for="(line,i) in form.lines" :key="line.lineNo"><td>{{i+1}}. {{product(line)}}</td><td>{{line.quantity}}</td><td>{{line.reserved}}</td><td>{{currentLine(line).reserved}}</td><td>{{currentLine(line).missing}}</td><td><a-input-number v-if="mode==='edit'" v-model="line.productionQuantity" :precision="6" :min="0" style="width:130px"/><span v-else>{{line.productionQuantity}}</span></td><td><a-input v-if="mode==='edit'" v-model="line.adjustReason" :max-length="500" placeholder="生产量与当前缺口不同时必填" style="min-width:240px"/><span v-else>{{line.adjustReason || '—'}}</span></td></tr></tbody></table></div>
    <div class="label">任务时间 *</div><a-input v-if="mode==='edit'" v-model="form.task_time" type="datetime-local" style="width:260px"/><div v-else>{{form.task_time ? form.task_time.replace('T',' ') : '未填写'}}</div>
    <div class="label">生产要求</div><a-textarea v-model="form.requirements" :disabled="mode!=='edit'" :max-length="4000" :rows="3" placeholder="包装、工艺、交期或其他生产要求" />
    <template v-if="mode!=='edit'">
     <h3>各车间接单进度</h3><p v-for="w in form.workshops" :key="w.workshop_no">{{workshops[w.workshop_no-1]}}　主任：{{userName(options['workshop'+w.workshop_no+'_director_id'])}}　{{workshopStates[w.workflow_status]}}　<a v-if="w.workshop_no===myWorkshop && w.workflow_status==='pending'" @click="act('accept',form)">本车间接单</a>　<a v-if="w.workshop_no===myWorkshop && ['accepted','scheduled'].includes(w.workflow_status)" @click="open(form,'plan')">安排本车间人员和班次</a></p><p v-if="!form.workshops || !form.workshops.length">待生产统筹分配车间。</p>
     <h3>统筹分配的产品与工序</h3><p>生产统筹按产品决定车间和先后工序；同工序可拆分到不同车间，各工序合计等于该产品生产数量。</p>
     <div class="table-scroll"><table class="details"><thead><tr><th>产品行</th><th>工序</th><th>车间</th><th>分配数量（吨）</th><th v-if="mode==='distribute'">操作</th></tr></thead><tbody><tr v-for="(row,i) in form.routes" :key="i"><td><a-select v-if="mode==='distribute'" v-model="row.lineNo" style="width:350px"><a-select-option v-for="line in positiveLines" :key="line.lineNo" :value="line.lineNo">第{{line.lineNo+1}}行 {{product(line)}}</a-select-option></a-select><span v-else>第{{row.lineNo+1}}行 {{product(form.lines[row.lineNo])}}</span></td><td><a-input-number v-if="mode==='distribute'" v-model="row.stageNo" :min="1" :max="10" :precision="0"/><span v-else>{{row.stageNo}}</span></td><td><a-select v-if="mode==='distribute'" v-model="row.workshopNo" style="width:140px"><a-select-option v-for="w in 3" :key="w" :value="w">{{workshops[w-1]}}</a-select-option></a-select><span v-else>{{workshops[row.workshopNo-1]}}</span></td><td><a-input-number v-if="mode==='distribute'" v-model="row.quantity" :min="0" :precision="6"/><span v-else>{{row.quantity}}</span></td><td v-if="mode==='distribute'"><a @click="form.routes.splice(i,1)">移除</a></td></tr></tbody></table></div><a-button v-if="mode==='distribute'" icon="plus" style="margin-top:12px" @click="addRoute">添加车间分配</a-button>
     <h3>{{mode==='plan'?workshops[myWorkshop-1]+'人员与班次':'各车间人员与班次'}}</h3>
     <div v-if="mode==='plan'" style="margin:12px 0"><a-select v-model="planRoute" style="width:600px" placeholder="选择统筹分配给本车间的工序"><a-select-option v-for="route in ownRoutes" :key="route.key" :value="route.key">{{route.label}}，分配{{route.quantity}}吨</a-select-option></a-select><a-button icon="plus" style="margin-left:8px" @click="addPlan">添加人员班次</a-button></div>
     <div class="table-scroll"><table class="details"><thead><tr><th>产品行</th><th>工序</th><th>车间</th><th>数量（吨）</th><th>负责人</th><th>人员</th><th>班次</th><th>计划开工</th><th>计划完成</th><th v-if="mode==='plan'">操作</th></tr></thead><tbody><tr v-for="(row,i) in form.plan" :key="i"><td>第{{row.lineNo+1}}行 {{product(form.lines[row.lineNo])}}</td><td>{{row.stageNo}}</td><td>{{workshops[row.workshopNo-1]}}</td><td><a-input-number v-if="mode==='plan'" v-model="row.quantity" :min="0" :precision="6" style="width:120px"/><span v-else>{{row.quantity}}</span></td><td><a-input v-if="mode==='plan'" v-model="row.leader" :max-length="100" style="width:110px"/><span v-else>{{row.leader}}</span></td><td><a-input v-if="mode==='plan'" v-model="row.staff" :max-length="1000" style="width:180px"/><span v-else>{{row.staff}}</span></td><td><a-input v-if="mode==='plan'" v-model="row.shift" :max-length="200" style="width:130px"/><span v-else>{{row.shift}}</span></td><td><a-input v-if="mode==='plan'" v-model="row.startDate" type="date"/><span v-else>{{row.startDate}}</span></td><td><a-input v-if="mode==='plan'" v-model="row.endDate" type="date"/><span v-else>{{row.endDate}}</span></td><td v-if="mode==='plan'"><a @click="form.plan.splice(i,1)">移除</a></td></tr><tr v-if="!form.plan.length"><td colspan="10">尚无人员排班记录。主任接收本车间任务后安排。</td></tr></tbody></table></div>
     <template v-if="['plan','distribute'].includes(mode)"><div class="label">协调或调整说明</div><a-textarea v-model="comment" :max-length="2000" :rows="2"/><a-checkbox v-if="form.gapChanged" v-model="confirmedGap" style="margin-top:10px">已与销售核对缺口变化，按联系表生产数量执行</a-checkbox></template>
    </template>
    <template v-if="form.materials && form.materials.length"><h3>领补退料记录</h3><p v-for="m in form.materials" :key="m.id">{{m.number}} / {{materialKinds[m.kind]}} / {{materialStates[m.workflow_status]}} / 第{{m.line_no+1}}行 工序{{m.stage_no}} {{workshops[m.workshop_no-1]}}</p><a @click="goMaterial(form.head_id)">查看领补退料明细</a></template>
    <production-execution-panel v-if="mode==='view'" :task="form" :options="options" read-only />
    <h3 v-if="form.history && form.history.length">操作记录</h3><a-timeline><a-timeline-item v-for="(h,i) in form.history" :key="i">{{date(h.created_at)}}　{{h.actor_name}}　{{actions[h.action]}}　{{h.comment}}<details><summary>查看当次明细</summary><pre>{{JSON.stringify(JSON.parse(h.payload_json),null,2)}}</pre></details></a-timeline-item></a-timeline>
    <div class="footer"><a-button @click="visible=false">关闭</a-button><a-button v-if="mode==='edit'" type="primary" :loading="saving" @click="save">保存草稿</a-button><a-button v-if="mode==='distribute'" type="primary" :loading="saving" @click="saveDistribution">下发车间任务</a-button><a-button v-if="mode==='plan'" type="primary" :loading="saving" @click="savePlan">保存车间安排</a-button></div>
   </a-spin>
  </j-modal>
  <a-modal :title="actions[actionName]" :visible="!!actionName" :confirm-loading="saving" @cancel="actionName=''" @ok="confirmAction"><p>{{actionRow.number}} / {{actionRow.order_number}}</p><a-alert v-if="actionGap" type="warning" show-icon message="预留已变化，请与销售协调生产数量。"/><a-textarea v-model="comment" :rows="3" :max-length="2000" :placeholder="['return','unapprove'].includes(actionName)?'请填写'+(actionName==='unapprove'?'反审核':'退回')+'原因':'操作说明（接单时如缺口变化，须填写协调说明）'"/><a-checkbox v-if="actionName==='accept' && actionGap" v-model="confirmedGap">已与销售核对，按联系表生产数量执行</a-checkbox><p v-if="actionName==='cancel'">撤销后不再作为有效生产任务；已经接单的任务不能在这里直接撤销。</p></a-modal>
  <a-modal title="生产人员配置" :visible="settings" :confirm-loading="saving" @cancel="settings=false" @ok="configure"><p>设置领导审核人、生产统筹和三位不同车间主任。主任账号变更后，新主任接管该车间已有任务。人员不足时，先在用户管理创建账号并分配生产管理菜单。</p><div class="label">领导审核账号</div><a-select v-model="reviewerId" style="width:100%"><a-select-option v-for="u in options.users" :key="u.id" :value="u.id">{{u.username}}（{{u.login_name}}）</a-select-option></a-select><div class="label">生产统筹账号</div><a-select v-model="coordinatorId" style="width:100%"><a-select-option v-for="u in options.users" :key="u.id" :value="u.id">{{u.username}}（{{u.login_name}}）</a-select-option></a-select><div v-for="w in 3" :key="w"><div class="label">{{workshops[w-1]}}主任</div><a-select v-model="directorIds[w-1]" style="width:100%"><a-select-option v-for="u in options.users" :key="u.id" :value="u.id">{{u.username}}（{{u.login_name}}）</a-select-option></a-select></div></a-modal>
 </a-card>
</template>
<script>
import {getAction,postAction} from '@/api/manage'
import ProductionExecutionPanel from './ProductionExecutionPanel'
export default {
 name:'ProductionTaskList',components:{ProductionExecutionPanel},
 data(){return {keyword:'',state:undefined,rows:[],selectedKeys:[],pagination:{current:1,pageSize:10,total:0,showSizeChanger:true},loading:false,saving:false,options:{users:[],workshopNos:[]},visible:false,mode:'view',form:{lines:[],plan:[],stock:{lines:[]},history:[]},settings:false,reviewerId:undefined,coordinatorId:undefined,directorIds:[undefined,undefined,undefined],planRoute:undefined,comment:'',confirmedGap:false,actionName:'',actionRow:{},actionGap:false,workshops:['一车间','二车间','三车间'],
 materialKinds:{issue:'领料',supplement:'补料',return:'退料'},materialStates:{draft:'草稿',pending:'待仓库确认',returned:'已退回',confirmed:'已确认',cancelled:'已撤销'},states:{draft:'草稿',pending:'待领导审核',returned:'已退回',approved:'待生产统筹分配',distributed:'各车间处理中',scheduled:'各车间已排班',cancelled:'已撤销'},workshopStates:{pending:'待主任接单',accepted:'主任已接单',scheduled:'已排班'},actions:{order_change:'统筹落实订单变更或停产',report_correct:'直接更正生产日报',execution_start:'确认实际开工',execution_report:'录入生产日报',flow_upgrade:'生产流程升级',distribute:'统筹分配车间',material_create:'创建领退料单',material_edit:'修改领退料单',material_submit:'领退料提交仓库',material_confirm:'仓库确认领退料',material_reject:'仓库退回领退料单',material_withdraw:'撤回领退料单',material_cancel:'撤销领退料单',material_delete:'删除领退料单',create:'创建',edit:'修改',submit:'提交审核',approve:'审核通过',unapprove:'反审核',return:'退回修改',withdraw:'撤回修改',cancel:'撤销联系表',accept:'主任接单',schedule:'安排车间与排班'},
 columns:[{title:'联系表编号',dataIndex:'number',width:240},{title:'销售订单',dataIndex:'order_number',width:240},{title:'客户',dataIndex:'customer_name',width:150},{title:'任务时间',dataIndex:'task_time',width:170,customRender:value=>value?value.replace('T',' '):'未填写'},{title:'交货日期',dataIndex:'delivery_date',width:120},{title:'各车间进度',key:'workshops',scopedSlots:{customRender:'workshops'},width:200},{title:'状态',dataIndex:'workflow_status',scopedSlots:{customRender:'state'},width:170},{title:'操作',key:'action',scopedSlots:{customRender:'action'},width:100}] }},
 computed:{canUnapprove(){const row=this.selected;return !!row && row.workflow_status==='approved' && this.options.currentUserId===this.options.reviewer_id && !(row.workshops||[]).length},selected(){return this.rows.find(r=>r.head_id===this.selectedKeys[0])},myWorkshop(){return this.options.workshopNos[0]},myWorkshopState(){return this.selected && (this.selected.workshops||[]).find(w=>w.workshop_no===this.myWorkshop)},ownRoutes(){const grouped={};for(const row of this.form.routes||[]){if(row.workshopNo!==this.myWorkshop)continue;const key=row.lineNo+'|'+row.stageNo+'|'+row.workshopNo;if(!grouped[key])grouped[key]={...row,key,quantity:0,label:'第'+(row.lineNo+1)+'行 '+this.product(this.form.lines[row.lineNo])+' / 工序'+row.stageNo};grouped[key].quantity+=Number(row.quantity)}return Object.values(grouped)},reviewable(){return !!this.selected && this.selected.workflow_status==='pending' && this.options.currentUserId===this.options.reviewer_id && this.selected.created_by!==this.options.currentUserId},positiveLines(){return this.form.lines.filter(line=>Number(line.productionQuantity)>0)}},
 created(){this.initialize()},watch:{'$route.query.orderId'(id){if(id)this.fromOrder(id)},'$route.query.viewId'(id){if(id)this.open({head_id:id},'view')}},
 methods:{
  goMaterial(id){this.visible=false;this.$router.push({path:'/factory/material_request',query:{taskId:String(id)}})},
  async request(path,body){const r=body===undefined?await getAction('/factoryProduction'+path):await postAction('/factoryProduction'+path,body);if(r.code!==200)throw new Error(r.message || (r.data&&r.data.message) || '操作失败');return r.data},
  error(e){this.$message.error(e.message || '请求失败')},date(value){return value?new Date(value).toLocaleString('zh-CN'):''},product(line){return line?[line.name,line.brand,line.standard,line.model].filter(Boolean).join(' / '):''},userName(id){const user=this.options.users.find(u=>u.id===id);return user?user.username+'（'+user.login_name+'）':'未配置'},
  currentLine(line){return (this.form.stock.lines || []).find(row=>row.lineNo===line.lineNo) || line},
  editable(row){return !!row && row.created_by===this.options.currentUserId && ['draft','returned','cancelled'].includes(row.workflow_status)},ownedState(states){return !!this.selected && this.selected.created_by===this.options.currentUserId && states.includes(this.selected.workflow_status)},
  async initialize(){try{this.options=await this.request('/options');this.reviewerId=this.options.reviewer_id;this.coordinatorId=this.options.coordinator_id;this.directorIds=[1,2,3].map(w=>this.options['workshop'+w+'_director_id']);await this.load();if(this.$route.query.viewId)await this.open({head_id:this.$route.query.viewId},'view');else if(this.$route.query.orderId)await this.fromOrder(this.$route.query.orderId)}catch(e){this.error(e)}},
  async load(reset=true){if(reset)this.pagination.current=1;this.loading=true;this.selectedKeys=[];try{const r=await this.request('/list?keyword='+encodeURIComponent(this.keyword)+'&state='+encodeURIComponent(this.state||'')+'&page='+this.pagination.current+'&size='+this.pagination.pageSize);this.rows=r.rows;this.pagination.total=r.total}catch(e){this.error(e)}finally{this.loading=false}},onPage(page){this.pagination.current=page.current;this.pagination.pageSize=page.pageSize;this.load(false)},
  async fromOrder(id){try{const source=await this.request('/source/'+id);if(source.task.length && source.task[0].workflow_status!=='cancelled'){const task=source.task[0];if(this.editable(task))await this.edit(task);else await this.open(task,'view');return}this.form={head_id:Number(id),version:source.task.length?source.task[0].version:undefined,number:source.task.length?source.task[0].number:'',order_number:source.order_number,customer_name:source.customer_name,delivery_date:source.delivery_date,task_time:'',requirements:source.requirements,stock:source.stock,lines:source.stock.lines.map(line=>({...line,productionQuantity:Number(line.missing),adjustReason:''})),plan:[],routes:[],workshops:[],history:[]};this.mode='edit';this.visible=true}catch(e){this.error(e)}},
  async edit(row){try{const d=await this.request('/'+row.head_id);const source=await this.request('/source/'+row.head_id);this.form={...d,stock:source.stock,lines:source.stock.lines.map(line=>{const old=d.lines[line.lineNo];return {...line,productionQuantity:row.workflow_status==='cancelled'?Number(line.missing):old.productionQuantity,adjustReason:row.workflow_status==='cancelled'?'':old.adjustReason}})};this.mode='edit';this.visible=true}catch(e){this.error(e)}},
  async open(row,mode){try{this.form=await this.request('/'+row.head_id);this.mode=mode;if(mode==='plan')this.form.plan=this.form.plan.filter(row=>row.workshopNo===this.myWorkshop);this.planRoute=undefined;this.comment='';this.confirmedGap=false;this.visible=true}catch(e){this.error(e)}},
  async save(){if(!this.form.task_time){this.$message.warning('请填写任务时间');return}if(!this.form.lines.some(line=>Number(line.productionQuantity)>0)){this.$message.warning('没有需要生产的数量，无需开联系表');return}if(this.form.lines.some(line=>Number(line.productionQuantity)!==Number(line.missing) && !(line.adjustReason||'').trim())){this.$message.warning('生产数量与缺口不同时，请填写调整原因');return}this.saving=true;try{await this.request('/'+this.form.head_id+'/save',{version:this.form.version,taskTime:this.form.task_time,requirements:this.form.requirements,lines:this.form.lines.map(line=>({lineNo:line.lineNo,productionQuantity:line.productionQuantity,adjustReason:line.adjustReason}))});this.visible=false;this.$message.success('已保存生产联系表草稿');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}},
  async act(action,row=this.selected){try{const d=await this.request('/'+row.head_id);this.actionRow=d;this.actionGap=d.gapChanged;this.comment='';this.confirmedGap=false;this.actionName=action}catch(e){this.error(e)}},
  async confirmAction(){if(['return','unapprove'].includes(this.actionName) && !this.comment.trim()){this.$message.warning('请填写原因');return}this.saving=true;try{await this.request('/'+this.actionRow.head_id+'/action',{version:this.actionRow.version,action:this.actionName,workshopNo:this.myWorkshop,comment:this.comment,confirmedGap:this.confirmedGap});this.actionName='';if(this.visible){this.form=await this.request('/'+this.actionRow.head_id);this.mode='view'}this.$message.success('操作成功');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}},
  addRoute(){const line=this.positiveLines[0];if(line)this.form.routes.push({lineNo:line.lineNo,stageNo:1,workshopNo:1,quantity:Number(line.productionQuantity)})},
  async saveDistribution(){this.saving=true;try{await this.request('/'+this.form.head_id+'/distribute',{version:this.form.version,routes:this.form.routes,comment:this.comment,confirmedGap:this.confirmedGap});this.visible=false;this.$message.success('已下发各车间，由各主任分别接单');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}},
  addPlan(){const route=this.ownRoutes.find(r=>r.key===this.planRoute);if(!route){this.$message.warning('请选择本人车间的产品工序');return}const assigned=this.form.plan.filter(row=>row.lineNo===route.lineNo && row.stageNo===route.stageNo).reduce((sum,row)=>sum+Number(row.quantity||0),0);this.form.plan.push({lineNo:route.lineNo,stageNo:route.stageNo,workshopNo:this.myWorkshop,quantity:route.quantity>assigned?route.quantity-assigned:null,leader:'',staff:'',shift:'',startDate:'',endDate:this.form.delivery_date})},
  async savePlan(){this.saving=true;try{await this.request('/'+this.form.head_id+'/plan',{version:this.form.version,workshopNo:this.myWorkshop,plan:this.form.plan,comment:this.comment,confirmedGap:this.confirmedGap});this.visible=false;this.$message.success('已保存车间安排和排班');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}},
  async configure(){this.saving=true;try{await this.request('/config',{reviewerId:this.reviewerId,coordinatorId:this.coordinatorId,workshop1DirectorId:this.directorIds[0],workshop2DirectorId:this.directorIds[1],workshop3DirectorId:this.directorIds[2]});this.settings=false;await this.initialize();this.$message.success('配置已保存')}catch(e){this.error(e)}finally{this.saving=false}}
 }
}
</script>
<style scoped>
.operator{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.label{font-weight:500;margin:12px 0 6px}h3{margin:22px 0 12px}.table-scroll{overflow-x:auto}.details{border-collapse:collapse;width:100%;min-width:1150px}.details td,.details th{border:1px solid #e8e8e8;padding:9px;text-align:left}.details th{background:#fafafa}.footer{display:flex;justify-content:flex-end;gap:10px;margin:20px 0}pre{white-space:pre-wrap;max-height:320px;overflow:auto}
</style>
